<?php namespace App\Models; use Illuminate\Database\Eloquent\Factories\HasFactory; use Illuminate\Database\Eloquent\Model; use Illuminate\Database\Eloquent\Relations\HasMany; use Illuminate\Database\Eloquent\SoftDeletes; class Purchase extends Model { use HasFactory,SoftDeletes; protected $fillable=['supplier_name','purchase_date','total_amount','payment_status','notes','user_id']; protected function casts():array{return ['purchase_date'=>'date','total_amount'=>'decimal:2'];} public function items():HasMany{return $this->hasMany(PurchaseItem::class);} public function user(){return $this->belongsTo(User::class);} }